import app from 'flarum/forum/app';
import Icon from 'flarum/common/components/Icon';
import { rarityName, t } from '../util';
import { openSticker } from './StickerModal';

/**
 * An album, set by set: what the member has (art, and ×N for spares) and
 * what they're missing (a silhouette: the server never sent the art).
 * Filters: everything, missing, spares.
 */
export default class Album {
  oninit() {
    this.filter = 'all';
  }
  view(vnode) {
    const {
      album,
      own
    } = vnode.attrs;
    const filters = ['all', 'missing', 'spares'];
    const keep = s => this.filter === 'all' || (this.filter === 'missing' ? !s.count : s.count > 1);
    if (!album.sets.length) {
      return m("div", {
        className: "StickerAlbum-empty"
      }, m(Icon, {
        name: "fas fa-note-sticky"
      }), m("p", null, t('album.no_sets')));
    }
    return m("div", {
      className: "StickerAlbum"
    }, m("div", {
      className: "StickerAlbum-filters",
      role: "tablist"
    }, filters.map(f => m("button", {
      className: `StickerChip ${this.filter === f ? 'is-active' : ''}`,
      role: "tab",
      "aria-selected": this.filter === f ? 'true' : 'false',
      onclick: () => this.filter = f
    }, t(`album.filter.${f}`)))), album.sets.map(set => ({
      set,
      shown: set.stickers.filter(keep)
    })).filter(({
      shown
    }) => shown.length || this.filter === 'all').map(({
      set,
      shown
    }) => {
      const have = set.stickers.filter(s => s.count).length;
      const pct = Math.round(have / set.stickers.length * 100);
      return m("section", {
        className: `StickerSet ${set.completedAt ? 'is-complete' : ''}`,
        key: set.id
      }, m("header", {
        className: "StickerSet-header"
      }, m("div", {
        className: "StickerSet-title"
      }, m("h3", null, set.name, set.completedAt ? m("span", {
        className: "StickerSet-done"
      }, m(Icon, {
        name: "fas fa-trophy"
      }), " ", t('album.complete')) : null), set.description ? m("p", null, set.description) : null), m("div", {
        className: "StickerSet-progress",
        "aria-label": t('album.progress_label', {
          have,
          total: set.stickers.length
        })
      }, m("span", {
        className: "StickerSet-count"
      }, have, m("small", null, "/", set.stickers.length)), m("span", {
        className: "StickerSet-bar"
      }, m("span", {
        style: {
          width: pct + '%'
        }
      })))), m("div", {
        className: "StickerGrid"
      }, shown.map(s => m(StickerTile, {
        sticker: s,
        onclick: () => openSticker({
          sticker: s,
          album,
          own
        })
      }))));
    }));
  }
}
export function StickerTile() {
  return {
    view: ({
      attrs: {
        sticker: s,
        onclick,
        compact
      }
    }) => m("button", {
      className: `StickerTile StickerTile--r${s.rarity} ${s.count ? '' : 'is-missing'} ${compact ? 'StickerTile--compact' : ''}`,
      onclick: onclick,
      title: `${s.name} · ${rarityName(s.rarity)}`
    }, m("span", {
      className: "StickerTile-art"
    }, m("img", {
      src: s.count ? s.small : s.sil,
      alt: "",
      loading: "lazy",
      draggable: "false"
    }), s.count > 1 ? m("span", {
      className: "StickerTile-count"
    }, "\xD7", s.count) : null), compact ? null : m("span", {
      className: "StickerTile-label"
    }, m("span", {
      className: "StickerTile-name"
    }, s.name), m("span", {
      className: "StickerTile-rarity"
    }, rarityName(s.rarity))))
  };
}

/** The member's own counts as a quick lookup, from their album. */
export function countsOf(album) {
  const out = {};
  for (const set of album?.sets || []) for (const s of set.stickers) out[s.id] = s.count;
  return out;
}

/** Every sticker in an album, by id. */
export function stickersOf(album) {
  const out = {};
  for (const set of album?.sets || []) for (const s of set.stickers) out[s.id] = s;
  return out;
}
export const isOwnAlbum = album => app.session.user && album && String(album.user.id) === app.session.user.id();
flarum.reg.add('ernestdefoe-sticker-book', 'forum/components/Album', Album);