import app from 'flarum/forum/app';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import username from 'flarum/common/helpers/username';
import { call, pushUsers, t, user } from '../util';
const MEDALS = ['🥇', '🥈', '🥉'];

/** The members with the most different stickers. */
export default class Board {
  oninit() {
    this.data = null;
    call('GET', '/board', undefined, true).then(data => {
      pushUsers(data.users);
      this.data = data;
    }).catch(() => this.data = {
      board: [],
      total: 0
    }).finally(() => m.redraw());
  }
  view() {
    if (!this.data) return m(LoadingIndicator, {
      display: "block"
    });
    const {
      board,
      total
    } = this.data;
    if (!board.length) return m("p", {
      className: "StickerTrades-empty"
    }, t('board.empty'));
    return m("ol", {
      className: "StickerBoard"
    }, board.map(([id, unique], i) => {
      const u = user(id);
      return m("li", {
        className: "StickerBoard-row"
      }, m("span", {
        className: "StickerBoard-rank"
      }, MEDALS[i] || i + 1), m(Link, {
        href: u ? app.route('user.stickers', {
          username: u.slug()
        }) : '#',
        className: "StickerBoard-who"
      }, m(Avatar, {
        user: u
      }), " ", m("span", null, username(u))), m("span", {
        className: "StickerBoard-bar"
      }, m("span", {
        style: {
          width: (total ? Math.round(unique / total * 100) : 0) + '%'
        }
      })), m("span", {
        className: "StickerBoard-n"
      }, t('board.count', {
        count: unique,
        total
      })));
    }));
  }
}
flarum.reg.add('ernestdefoe-sticker-book', 'forum/components/Board', Board);